#include "TrinketCatalogue.hpp"
namespace elysium::content { bool TrinketCatalogue::add(TrinketRow r,std::string&w){if(!r.id||!r.benefitPassive||r.acquisitionRefs.empty()){w="incomplete trinket";return false;}if(!rows_.emplace(r.id,std::move(r)).second){w="duplicate trinket";return false;}return true;} bool TrinketCatalogue::validatePassiveRefs(const std::unordered_map<ContentId,bool>& p,std::string&w)const{for(auto&[_,r]:rows_){if(!p.count(r.benefitPassive)||(r.drawbackPassive&&!p.count(r.drawbackPassive))){w="unsupported passive";return false;}}return true;} bool TrinketCatalogue::canEquip(ContentId id,std::uint16_t level,const std::vector<ContentId>&eq,std::string&w)const{auto i=rows_.find(id);if(i==rows_.end()){w="unknown trinket";return false;}if(level<i->second.minLevel){w="level gate";return false;}if(i->second.uniqueEquip)for(auto e:eq)if(e==id){w="unique equip conflict";return false;}return true;} }